style.css:
@-moz-document url-prefix("https://web.whatsapp.com/") {
body {
    background: linear-gradient(to bottom, #f5e6fa, #e8dff5) !important;
  }

  .app-wrapper-web {
    background-color: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(6px) !important;
  }

  ._3q4NP {
    background: url('https://i.imgur.com/3zhYUSM.jpg') center/cover no-repeat !important;
    opacity: 0.9;
  }

  ._1ays2 {
    background-color: rgba(250, 240, 250, 0.8) !important;
  }

  .message-in {
    background-color: rgba(230, 230, 250, 0.75) !important;
    color: #4B0082 !important;
  }

  .message-out {
    background-color: rgba(216, 191, 216, 0.75) !important;
    color: #4B0082 !important;
  }

  ._2vDPL, ._3OvU8, ._1V6iF {
    background-color: rgba(255, 255, 255, 0.5) !important;
    color: #4B0082 !important;
  }

  ._1MXsz {
    border: 1px solid #dda0dd !important;
  }

  ._1MXsz:hover {
    background-color: rgba(221, 160, 221, 0.4) !important;
  }

  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #f5e6fa;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #b57edc;
    border-radius: 10px;
  }
}
